using System;using System.IO;using System.Text;using System.Collections.Generic;
// Native passive-object membership per room map (FG360).
// Source: data/passive-objects-FG360.dat, generated by local-run/pvf/gen_passive_objects_fg360.py.
// Original semantics (rednf CMap/set_map.inc:122-131 + BattleFieldLCB/DestroyPassiveObject.inc):
//   * set_map pushes the first int of every `[passive object]` row of the room .map into
//     CMap::m_passiveObjectList (`[special passive object]` rows are NOT in that list);
//   * a die packet (DisPatcherCore/dispatch_sig_16.inc) carries a passiveFlag byte at
//     tail+6, and when it is 1 the packet's m_mobSeq is that object id and the native
//     server answers it with CParty::DestroyPassiveObject(mobSeq), which accepts the
//     report only when the id appears in the current map's list.
// This table is that membership list, so a destruction report can be validated
// the same way instead of being rejected as an out-of-range actor (which is what the
// old parser did - every passive object id is above the monster uid range).
// FG387 appends each map's `[special passive object]` rows after the native list. The
// client never reports those either (their drop rows ride in the room body), so the
// room-clear synthetic feed is the only channel an objective naming one can use
// (5744 武器箱 8956, 5757 10149, 5759 8961, 5746/5758 粮食袋 8963, 5775 10137,
// 5867 10197-10199, 5901 10231).
class Offline70PassiveObjectsFG360{
 internal const string Magic="FG360PO1";internal const int MaximumBytes=4194304;
 internal static readonly Dictionary<ushort,ushort[]> Table=new Dictionary<ushort,ushort[]>();
 internal static int Maps,Objects;
 internal static void Load(string path){
  if(Table.Count!=0)return;byte[] b=File.ReadAllBytes(path);if(b.Length<74||b.Length>MaximumBytes)throw new InvalidDataException("Passive object catalog size");
  if(Encoding.ASCII.GetString(b,0,8)!=Magic)throw new InvalidDataException("Passive object catalog magic");
  if(Encoding.ASCII.GetString(b,8,64).ToUpperInvariant()!=Offline70QuestCatalogFG.CurrentPvf)throw new InvalidDataException("Passive object catalog PVF");
  int count;
  using(BinaryReader r=new BinaryReader(new MemoryStream(b,false),Encoding.ASCII)){
   r.BaseStream.Position=72;count=r.ReadUInt16();if(count<1||count>8192)throw new InvalidDataException("Passive object map count");
   for(int i=0;i<count;i++){
    ushort map=r.ReadUInt16(),rows=r.ReadUInt16();if(map==0||rows<1||rows>512||Table.ContainsKey(map))throw new InvalidDataException("Passive object map header");
    ushort[] ids=new ushort[rows];
    for(int k=0;k<rows;k++){ushort id=r.ReadUInt16();if(id==0)throw new InvalidDataException("Passive object id");ids[k]=id;}
    Table.Add(map,ids);Maps++;Objects+=rows;
   }
   if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Passive object catalog trailing bytes");
  }
 }
 // Native DestroyPassiveObject: the id must be declared by the room's own map file.
 internal static bool Declares(ushort map,ushort id){ushort[] ids;if(!Table.TryGetValue(map,out ids))return false;foreach(ushort row in ids)if(row==id)return true;return false;}
}
